<script setup>
import {ref,onMounted,onUnmounted,computed} from 'vue';
import {Download,Upload,X,RefreshCw,Copy} from 'lucide-vue-next';
import {useAtlas} from './stores/atlas';
import TreeNode from './components/TreeNode.vue';
import DetailPanel from './components/DetailPanel.vue';
const store=useAtlas();const showData=ref(false),showHelp=ref(false),url=ref(''),newTopic=ref(''),message=ref('');let timer;
const requestedUrl=new URLSearchParams(location.search).get('source');
onMounted(async()=>{await store.init();url.value=requestedUrl||store.sharedUrl;if(requestedUrl && store.sharedUrl!==requestedUrl){showData.value=true;message.value='You already have a saved local tree. Load this shared URL to replace it, or close this dialog to keep your current tree.';}timer=setInterval(()=>store.now=Date.now(),30000);});onUnmounted(()=>clearInterval(timer));
function canReplace(){return !store.dirty||window.confirm('This replaces your local tree and progress. Export your JSON first if you want to keep it. Continue?');}
async function importFile(e){const f=e.target.files[0];if(!f)return;try{if(f.size>5e6)throw Error('File must be smaller than 5 MB.');const data=JSON.parse(await f.text());if(canReplace()){store.replace(data,f.name);message.value='JSON imported successfully.';}}catch(err){store.error=`Import failed: ${err.message}`;}finally{e.target.value='';}}
async function load(){if(canReplace()){await store.loadUrl(url.value);if(!store.error)message.value='Shared JSON loaded. Edits stay on this device until you export and replace the hosted file.';}}
async function copyLink(){try{const u=new URL(location.href);u.search='';u.searchParams.set('source',store.sharedUrl);await navigator.clipboard.writeText(u.href);message.value='Viewer link copied. Open it on your other device.';}catch{message.value='Clipboard is unavailable. Use the viewer URL shown below.';}}
const shareLink=computed(()=>{const u=new URL(location.href);u.search='';u.searchParams.set('source',store.sharedUrl);return u.href;});
</script>
<template>
<div class="app">
  <main class="notebook">
    <header class="notebook__header"><div><h1>🌳 Algorithm tree</h1></div><div class="notebook__tools"><button class="button" @click="showHelp=true">? Guide</button><button class="button" @click="showData=true">↗ JSON & sharing</button><button class="button" :disabled="!store.data" @click="store.download()">↓ Export JSON</button></div></header>
    <div v-if="store.error" class="alert" role="alert">{{store.error}}<button class="icon-button" aria-label="Dismiss error" @click="store.error=''">×</button></div>
    <div class="notebook__toolbar"><label class="notebook__search">⌕ <input v-model="store.query" placeholder="Find a pattern, problem, or note…" aria-label="Search tree"/></label><select v-model="store.topicId" aria-label="Choose topic"><option value="all">All topics</option><option v-for="topic in store.data?.topics" :key="topic.id" :value="topic.id">{{topic.title}}</option></select><select v-model="store.filter" aria-label="Filter tree"><option value="all">All branches</option><option value="due">🔔 Review due</option><option value="completed">✅ Learned</option><option value="primary">⭐ Top 150</option><option value="later">Later</option></select></div>
    <div class="notebook__controls"><div><button @click="store.expandAll(true)">Expand all</button><span> · </span><button @click="store.expandAll(false)">Collapse all</button><label><input type="checkbox" v-model="store.showNotes"/> Show notes</label></div><button class="notebook__queue" @click="store.filter=store.filter==='due'?'all':'due';store.topicId='all'">🔔 {{store.due.length}} to re-read</button></div>
    
    <p v-if="store.query||store.filter!=='all'" class="notebook__hint">Showing matches with their parent branches. Clear the search and choose “All branches” to collapse freely.</p>
    <p v-if="store.busy" class="empty" role="status">Loading your tree…</p>
    <ul v-else-if="store.visibleTopics.length" class="outline"><TreeNode v-for="topic in store.visibleTopics" :key="topic.id" :node="topic"/></ul>
    <div v-else class="empty"><p>No matching branches.</p><button class="button" @click="store.query='';store.filter='all';store.topicId='all'">Show all</button></div>
    <form v-if="store.data" class="notebook__add" @submit.prevent="store.addChild(null,newTopic);store.selectedId=null;newTopic='' "><span>＋</span><input v-model="newTopic" placeholder="Add a new topic…" aria-label="New topic name" required/><button class="button">Add topic</button></form>
    <footer class="notebook__footer">{{store.nodes.length}} branches · {{store.problemCount}} primary problems <span>{{store.source}}{{store.dirty?' · local edits':''}}</span></footer>
  </main>
  <DetailPanel/>
  <div v-if="showData||showHelp" class="modal" @click.self="showData=false;showHelp=false"><section class="modal__card" role="dialog" aria-modal="true" :aria-label="showHelp?'How to use the atlas':'Data and sharing'" @keydown.esc="showData=false;showHelp=false"><div class="detail__top"><span class="eyebrow">{{showHelp?'A QUICK FIELD GUIDE':'YOUR DATA, YOUR FILE'}}</span><button class="icon-button" autofocus aria-label="Close dialog" @click="showData=false;showHelp=false"><X :size="20"/></button></div>
    <template v-if="showData"><p v-if="store.error" class="alert" role="alert">{{store.error}}</p><h2>Take your map anywhere.</h2><p>Open the same hosted JSON on your phone and computer. Changes are saved locally; export and replace the shared file to carry them across devices.</p><div class="modal__buttons"><label class="button"><Upload :size="16"/>Import JSON<input class="file-input" type="file" accept=".json,application/json" @change="importFile"/></label><button class="button" :disabled="!store.data" @click="store.download()"><Download :size="16"/>Export full snapshot</button></div><form @submit.prevent="load"><label class="field">Shared JSON URL<input v-model="url" type="url" placeholder="https://your-site.vercel.app/taxonomy.json" required/></label><button class="button button--green" :disabled="store.busy"><RefreshCw :size="15"/>{{store.busy?'Loading…':'Load shared JSON'}}</button></form><div v-if="store.sharedUrl" class="modal__share"><button class="button" @click="copyLink"><Copy :size="15"/>Copy viewer link</button><label class="field">Open on another device<input readonly :value="shareLink"/></label></div><p v-if="message" class="modal__message" role="status">{{message}}</p><p class="detail__hint">URL loading is read-only. Use a raw JSON URL with CORS enabled, or the taxonomy.json file deployed with this app. No tokens or accounts are required. Export before reloading a shared file; reloading replaces local changes.</p><p class="detail__hint">There is no automatic multi-device merge. Make changes on one device, publish its exported file, then reload it on the other.</p></template>
    <template v-else><h2>Patterns first. Practice follows.</h2><p>Use ▾ to fold a branch. Notes appear directly below the text. Use + to add a child branch, 📝 to add a note, and the branch title or ⚙ to edit or set a review interval.</p><ul class="modal__guide"><li v-for="item in store.data?.legend" :key="item">{{item.replace(/^• /,'')}}</li></ul><p>Review bells are in-app reminders, not background push notifications. “Learned” applies only to the selected branch. Newly added problems are never automatically marked solved.</p><h3>Original taxonomy overview</h3><p v-for="line in store.data?.overview" :key="line">{{line}}</p></template>
  </section></div>
</div>
</template>
